/**
 * dreamerv3.ts - DreamerV3 World-Model Rollout and Value Backup (teaching core)
 *
 * ---------------------------------------------------------------------------
 * What it does
 * ---------------------------------------------------------------------------
 * DreamerV3 learns a world model and then trains its actor inside imagined
 * rollouts generated by that model. The teachable core is exactly this loop:
 * start from a latent state, repeatedly apply a learned transition model to a
 * chosen action, collect the predicted reward, and add up the discounted
 * rewards to form the value target used to train the policy.
 *
 * ---------------------------------------------------------------------------
 * Scope of the model
 * ---------------------------------------------------------------------------
 * This is a SMALL DETERMINISTIC TEACHING MODEL, not DreamerV3. It uses a fixed
 * two-dimensional latent, a hand-written transition and reward function, and a
 * prescribed action sequence. It omits the RSSM, categorical latents, symlog
 * rewards, actor-critic learning, and data collection. Only the imagined
 * rollout and discounted value backup are shown, and those are exact.
 *
 * ---------------------------------------------------------------------------
 * Complexity
 * ---------------------------------------------------------------------------
 *   Time:  O(H * d^2) for H imagined steps with latent dimension d
 *   Space: O(H * d) for the stored latent trajectory
 *
 * ---------------------------------------------------------------------------
 * Visualization mapping
 * ---------------------------------------------------------------------------
 *   - Each frame shows the current latent state as two grid cells.
 *   - meta carries each step's reward, discounted contribution, and running value.
 *   - The final frame reports the total imagined value.
 */

import type { AlgorithmModule, VisualEntity, VisualFrame } from "@/types";

interface Input {
    h0?: number[];
    actions?: number[];
    gamma?: number;
}

export const WORLD_M = [
    [
        [0.8, -0.3],
        [0.2, 0.7],
    ],
    [
        [0.1, 0.9],
        [-0.6, 0.3],
    ],
    [
        [0.5, 0.5],
        [0.5, -0.5],
    ],
];
export const WORLD_B = [
    [0.1, -0.1],
    [0, 0.2],
    [-0.2, 0.1],
];
export const WORLD_C = [
    [1, 0.5],
    [0.3, 1.2],
    [-0.8, 0.4],
];

const clamp = (v: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, v));

/** One latent dynamics and reward step of the toy world model. */
export function worldStep(h: number[], action: number): { next: number[]; reward: number } {
    const a = clamp(Math.floor(action), 0, 2);
    const M = WORLD_M[a] ?? WORLD_M[0]!;
    const bias = WORLD_B[a] ?? WORLD_B[0]!;
    const c = WORLD_C[a] ?? WORLD_C[0]!;
    const next = M.map((row, i) => Math.tanh((row[0] ?? 0) * (h[0] ?? 0) + (row[1] ?? 0) * (h[1] ?? 0) + (bias[i] ?? 0)));
    const reward = clamp((c[0] ?? 0) * (h[0] ?? 0) + (c[1] ?? 0) * (h[1] ?? 0), -1, 1);
    return { next, reward };
}

/** Imagine H steps and return the discounted reward backup. */
export function dreamerRollout(h0: number[], actions: number[], gamma: number) {
    const steps: Array<{ state: number[]; nextState: number[]; reward: number; contribution: number }> = [];
    let h = h0.slice();
    let value = 0;
    for (let t = 0; t < actions.length; t += 1) {
        const { next, reward } = worldStep(h, actions[t] ?? 0);
        const contribution = gamma ** t * reward;
        value += contribution;
        steps.push({ state: h.slice(), nextState: next.slice(), reward, contribution });
        h = next;
    }
    return { steps, value, finalState: h };
}

function makeCells(state: number[]): VisualEntity[] {
    return state.map((value, i) => ({
        id: `latent-${i}`,
        type: "cell" as const,
        label: value.toFixed(2),
        value,
        state: "active" as const,
        x: 0,
        y: 0,
        width: 0,
        height: 0,
        metadata: { row: 0, col: i, dim: i },
    }));
}

/** The DreamerV3 teaching generator (imagined rollout and value backup). */
function* run(input: unknown): Generator<VisualFrame, void, unknown> {
    const task = (input as Input | null) ?? {};
    const h0 = task.h0 ?? [0, 0];
    const actions = task.actions ?? [0, 1, 2, 0];
    const gamma = typeof task.gamma === "number" ? clamp(task.gamma, 0, 1) : 0.9;
    const rollout = dreamerRollout(h0, actions, gamma);
    const rewards = rollout.steps.map((s) => s.reward);
    const contributions = rollout.steps.map((s) => s.contribution);
    const states = [h0, ...rollout.steps.map((s) => s.nextState ?? s.state)];
    const base = {
        rows: 1,
        cols: h0.length,
        d: h0.length,
        horizon: actions.length,
        gamma,
        actions,
        rewards,
        contributions,
    };

    let step = 0;
    yield {
        stepNumber: step,
        entities: makeCells(h0),
        edges: [],
        description: `Start an imagined rollout of ${actions.length} steps from latent [${h0.join(", ")}] with discount ${gamma}.`,
        codeLineNumber: 0,
        layout: "grid",
        meta: { ...base, phase: "setup", value: 0, states: states.flat(), valueSeries: [] },
    };
    step += 1;

    for (let t = 0; t < rollout.steps.length; t += 1) {
        const current = rollout.steps[t];
        yield {
            stepNumber: step,
            entities: makeCells(current?.state ?? h0),
            edges: [],
            description: `Imagined step ${t}, action ${actions[t]}: reward ${(current?.reward ?? 0).toFixed(3)}, discounted contribution ${(current?.contribution ?? 0).toFixed(3)}.`,
            codeLineNumber: 2,
            layout: "grid",
            meta: {
                ...base,
                phase: "rollout",
                t,
                value: contributions.slice(0, t + 1).reduce((a, b) => a + b, 0),
                states: states.flat(),
                valueSeries: contributions.slice(0, t + 1),
            },
        };
        step += 1;
    }

    yield {
        stepNumber: step,
        entities: makeCells(rollout.finalState),
        edges: [],
        description: `Done: total imagined value ${rollout.value.toFixed(3)} from ${actions.length} discounted reward(s).`,
        codeLineNumber: 5,
        layout: "grid",
        meta: {
            ...base,
            phase: "done",
            value: rollout.value,
            states: states.flat(),
            valueSeries: contributions,
            converged: true,
        },
    };
}

/** The DreamerV3 teaching module. */
const module: AlgorithmModule = {
    education: {
        intuition:
            "A model-based agent does not have to wait for the real world to hand it experience. It predicts what the next latent state and reward would be for an action, repeats that prediction into the future, and uses the imagined rewards as a training target. The backup is the same discounted sum used in reinforcement learning, except the transitions come from the learned world model rather than the environment.",
        invariants: [
            "Each imagined step uses the previous latent state as its input.",
            "The reward is predicted from the state before applying the transition.",
            "The value target is the sum of rewards discounted by gamma to the power of the step index.",
        ],
        correctness:
            "The rollout is a deterministic recurrence h_{t+1} = f(h_t, a_t) with reward r_t = g(h_t), so an independent replay of the same recurrence reproduces every state and reward exactly. The value is defined as sum of gamma^t r_t; accumulating the contribution gamma^t r_t step by step gives that sum. Setting gamma to zero keeps only the first reward, and a horizon of one keeps exactly one term, which are the expected edge cases.",
        complexityRationale:
            "Each of the H steps multiplies a two by two matrix by a two-vector and evaluates two more dot products, O(d^2) per step for latent dimension d, so O(H * d^2) total. Storing the imagined trajectory uses O(H * d) space.",
        uses: [
            "Teaching model-based reinforcement learning and imagination rollouts",
            "Understanding discounted value targets before actor-critic methods",
            "A stepping stone to world models such as DreamerV3",
        ],
        references: [
            "Hafner et al., Mastering Diverse Domains through World Models (DreamerV3), Nature 2025",
            "Hafner et al., Dream to Control: Learning Behaviors by Latent Imagination, ICLR 2020",
        ],
        workedExample:
            "Starting from latent (0, 0) with action zero, the toy reward is zero because both state channels are zero, and the transition uses tanh to produce a small new latent. Taking four imagined actions with gamma 0.9 adds four discounted rewards; the last one is weighted by 0.9 cubed.",
    },
    id: "dreamerv3",
    name: "DreamerV3 Rollout (Teaching Core)",
    category: "ml-ai",
    complexity: { time: "O(H * d^2)", space: "O(H * d)" },
    defaultInput: { h0: [0, 0], actions: [0, 1, 2, 0], gamma: 0.9 },
    visualType: "grid",
    run,
    pseudocode: [
        "start from the initial latent state",
        "for each imagined step choose the prescribed action",
        "predict the reward from the current latent state",
        "apply the transition model to obtain the next latent",
        "add gamma to the step power times the reward to the value",
        "store the state, reward, and discounted contribution",
        "done: report the total imagined value",
    ],
};

export default module;
